// Pega todos os itens de entrada
const items = $input.all();

// Pega a hora atual (0-23) usando Luxon/$now
const hour = $now.hour; // se quiser forçar fuso: $now.setZone('America/Sao_Paulo').hour

let greeting = 'Boa noite'; // default

if (hour >= 5 && hour < 12) {
  greeting = 'Bom dia';
} else if (hour >= 12 && hour < 18) {
  greeting = 'Boa tarde';
}

// Adiciona o campo em cada item
for (const item of items) {
  item.json.saudacao = greeting;
}

return items;

// ATENÇÃO (migração WAHA): este caminho de campo é uma MELHOR TENTATIVA, não foi confirmado com um áudio real da WAHA (Fase 0 só testou mensagens de texto).
// Antes de confiar neste nó em produção, envie um áudio de teste pela sessão WAHA, capture o payload do webhook e confirme o caminho real do base64/mídia.
const payload = $('Webhook').first().json.payload;
const base64 = payload?.media?.data || payload?.media?.base64 || payload?._data?.Message?.base64;

return [
  {
    json: {
      ...$json
    },
    binary: {
      data: {
        data: base64,
        mimeType: 'audio/ogg',
        fileName: 'audio.ogg'
      }
    }
  }
];

