function estaNoHorarioDeAtendimento() {
  const agora = $now; // Luxon DateTime do n8n
  const diaSemana = agora.weekday; // 1 = segunda, ..., 6 = sábado, 7 = domingo
  const minutosAgora = agora.hour * 60 + agora.minute;

  const inicio = 8 * 60;   // 08:00
  const fimSemana = 20 * 60; // 20:00
  const fimSabado = 14 * 60; // 14:00

  if (diaSemana >= 1 && diaSemana <= 5) {
    return minutosAgora >= inicio && minutosAgora < fimSemana;
  }

  if (diaSemana === 6) {
    return minutosAgora >= inicio && minutosAgora < fimSabado;
  }

  return false; // domingo
}

return [
  {
    json: {
      emHorarioAtendimento: estaNoHorarioDeAtendimento()
    }
  }
];
